import inspect
import sys
from threading import RLock

from abc import ABCMeta
import logging

from ute_common_util.version_selector import VersionSelector, Version

logger = logging.getLogger('agent_ute')


class DeprecatedSingleton(ABCMeta):
    """A metaclass which limits the number of class instances to 1."""

    _instance = None
    _instance_lock = RLock()

    def __call__(cls, *args, **kwargs):
        logger.debug("Object DeprecatedSingleton is deprecated")
        if cls._instance is None:
            with cls._instance_lock:
                if cls._instance is None:
                    cls._instance = super(DeprecatedSingleton, cls).__call__(*args, **kwargs)
        return cls._instance


class NewSingleton(ABCMeta):
    """
    A metaclass which limits the number of class instances to 1 with specified call arguments. This singleton can be
    used only with named arguments. Passing unnamed arguments will raise error. Single instance are created per class
    which are singleton. Meaningful_arguments must be defined if you want to create new object when certain parameter is
    changed. Into meaningful_arguments attribute put names of arguments which should be taken into account. If you do
    not put any names of arguments for certain singleton class, it will always return the same object.
    """

    _instance_lock = RLock()
    _all_instances = {}
    meaningful_arguments = []
    _classes_args = {}

    def __call__(cls, *args, **kwargs):
        """Here cls is like self but on classes that metaclass created"""

        with cls._instance_lock:
            cls._check_if_args_are_empty(args)
            instance = super(NewSingleton, cls).__call__(*args, **kwargs)  # This is needed for validating all required
            instance = NewSingleton._return_instance(cls, kwargs, instance)  # arguments without meaningful arguments -
            return instance                                             # tests with SingletonClassWithInit show case

    @classmethod
    def _return_instance(cls, klass, kwargs, instance):
        cls._read_class_default_and_meaningful_args(klass)
        meaningful_args = cls._prepare_meaningful_args(kwargs, klass)
        if cls._is_instance_called_with_different_arguments(meaningful_args, klass):
            cls._add_instance_with_arguments(klass, instance, kwargs, meaningful_args)
        instance = cls._get_instance(meaningful_args, klass)
        logger.debug("Singleton {cls} object ({obj}) created with {kwargs}".format(cls=instance.__class__.__name__,
                                                                                   obj=str(instance), kwargs=kwargs))
        return instance

    @classmethod
    def _read_class_default_and_meaningful_args(cls, klass):
        if klass not in cls._classes_args.keys():
            is_init_available = inspect.ismethod if sys.version_info[0] == 2 else inspect.isfunction
            if is_init_available(klass.__init__):
                inspect_default_args = inspect.getargspec if sys.version_info[0] == 2 else inspect.getfullargspec
                arguments, _, _, defaults = inspect_default_args(klass.__init__)[:4]  # This sublist is needed only
            else:                                                                     # in python3 but works on python2
                arguments, defaults = [], ()
            if defaults is None:
                defaults = ()
            default_args = dict(zip(arguments[-len(defaults):], defaults))

            if not hasattr(klass, "meaningful_arguments"):
                meaningful_arguments = []
            else:
                meaningful_arguments = getattr(klass, "meaningful_arguments")

            cls._classes_args[klass] = {}
            cls._classes_args[klass]["meaningful_args"] = meaningful_arguments
            cls._classes_args[klass]["default_args"] = default_args

    @classmethod
    def _prepare_meaningful_args(cls, kwargs, klass):
        if kwargs == {}:
            dic = {}
            return cls._add_missing_meaningful_values(dic, klass)
        else:
            dic = {key: value for key, value in kwargs.items() if key in cls._classes_args[klass]["meaningful_args"]}
            return cls._add_missing_meaningful_values(dic, klass)

    @classmethod
    def _is_instance_called_with_different_arguments(cls, meaningful_args, klass):
        _hash = cls._get_hash(klass, meaningful_args)
        if _hash in cls._all_instances.keys():
            return False
        else:
            return True

    @classmethod
    def _add_instance_with_arguments(cls, klass, instance, kwargs, meaningful_args):
        _hash = cls._get_hash(klass, meaningful_args)
        cls._all_instances[_hash] = {
            "instance": instance,
            "kwargs": kwargs,
            "meaningful_args": meaningful_args}

    @classmethod
    def _get_instance(cls, meaningful_args, klass):
        _hash = cls._get_hash(klass, meaningful_args)
        return cls._all_instances[_hash]["instance"]

    @classmethod
    def _add_missing_meaningful_values(cls, dic, klass):
        for key in cls._classes_args[klass]["meaningful_args"]:
            if key not in dic.keys():
                if key in cls._classes_args[klass]["default_args"].keys():
                    dic[key] = cls._classes_args[klass]["default_args"][key]
        return dic

    @classmethod
    def _check_if_args_are_empty(cls, args):
        if len(args) > 0:
            raise Exception("Singleton can only be sensitive on named arguments")

    @classmethod
    def _get_hash(cls, klass, meaningful_args):
        return hash(klass.__name__ + str(meaningful_args))


class SingletonVersionSelector(VersionSelector):

    @classmethod
    def all_versions(cls):
        """Implemented abstract method"""

        return [
            Version(DeprecatedSingleton, deprecated=True, default=True),
            Version(NewSingleton, deprecated=False, default=False)
        ]


Singleton = SingletonVersionSelector()
